  before_rows jsonb:=$src_before$[{"id":"R-111-2-14","subject":"社會工作研究方法","year":"111","round":"第二次","qno":"14","major":"抽樣","topic":"抽樣誤差 > 便利抽樣樣本偏誤","keywords":"便利抽樣, 樣本偏誤, 代表性, 回收率, 網路調查","question":"承上題，此研究的資料蒐集方法最大的缺點為何？","opt_a":"樣本偏誤","opt_b":"地理範圍受限","opt_c":"成本過高","opt_d":"回收率低","answer":"A","exp_why":"承上題,便利抽樣(放網路群組)最大的缺點是「樣本偏誤」(自願與同溫層偏差);(A)。","exp_others":"(B)地理範圍受限、(C)成本過高、(D)回收率低——皆非便利抽樣「最核心」的缺點。","exp_trap":"便利抽樣最大問題是「樣本不具代表性」(誰方便誰填,偏誤大)。","exp_raw":"","mnemonic":"便利抽樣最大缺點=樣本偏誤(代表性差)。","extension":"抽樣誤差;樣本偏誤。","law":"","mistake":"概念混淆","source_exam_code":"111110","source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=105&code=111110&q=1&s=0406&t=Q","analysis_status":"ready","analysis_attempts":0,"analysis_error":null,"analysis_started_at":null,"analysis_completed_at":null,"legal_status":"not_applicable","legal_checked_at":null,"legal_note":null,"legal_source_url":null,"legal_canonical_names":[],"accepted_answers":null,"grading_mode":"standard","analysis_last_attempt_at":null},{"id":"R-111-2-15","subject":"社會工作研究方法","year":"111","round":"第二次","qno":"15","major":"抽樣","topic":"非機率抽樣 > 滾雪球抽樣應用","keywords":"滾雪球抽樣, 失聯移工, 隱匿對象, 簡單隨機, 分層抽樣","question":"承上題，若該社工也想要進一步了解北部地區移工失聯的現象，由於受訪對象隱匿（難以尋覓）的特性，下列何種方法適合？","opt_a":"簡單隨機抽樣（simple random sampling）","opt_b":"分層抽樣（stratified sampling）","opt_c":"滾雪球抽樣（snowball sampling）","opt_d":"叢集抽樣（cluster sampling）","answer":"C","exp_why":"要研究「失聯(隱匿、難尋)」的移工,適合滾雪球抽樣(由受訪者轉介);(C)。","exp_others":"(A)簡單隨機、(B)分層、(D)叢集抽樣——皆需可掌握的母體名單,不適合隱匿母群。","exp_trap":"隱匿、無名單的對象(失聯移工)只能「一個介紹一個」滾雪球。","exp_raw":"","mnemonic":"滾雪球抽樣=研究隱匿難尋對象(如失聯移工)。","extension":"非機率抽樣;滾雪球抽樣。","law":"","mistake":"概念混淆","source_exam_code":"111110","source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=105&code=111110&q=1&s=0406&t=Q","analysis_status":"ready","analysis_attempts":0,"analysis_error":null,"analysis_started_at":null,"analysis_completed_at":null,"legal_status":"not_applicable","legal_checked_at":null,"legal_note":null,"legal_source_url":null,"legal_canonical_names":[],"accepted_answers":null,"grading_mode":"standard","analysis_last_attempt_at":null},{"id":"R-111-2-17","subject":"社會工作研究方法","year":"111","round":"第二次","qno":"17","major":"研究邏輯","topic":"研究設計 > 分析單位辨識","keywords":"分析單位, 社會工作師, 個人, 薪資所得, 機構","question":"承上題，該研究之分析單位為何？","opt_a":"社會福利機構","opt_b":"薪資所得","opt_c":"社會工作師","opt_d":"全國各縣市","answer":"C","exp_why":"承上題,研究「全國社工師的薪資」——分析單位是社會工作師(每位社工師);(C)。","exp_others":"(A)社會福利機構、(B)薪資所得是「變項」、(D)全國各縣市——皆非本題的分析對象。","exp_trap":"分析單位=「結論所描述的對象」;本題是個別社工師。","exp_raw":"","mnemonic":"分析單位=社會工作師(研究其薪資)。","extension":"研究設計;分析單位。","law":"","mistake":"概念混淆","source_exam_code":"111110","source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=105&code=111110&q=1&s=0406&t=Q","analysis_status":"ready","analysis_attempts":0,"analysis_error":null,"analysis_started_at":null,"analysis_completed_at":null,"legal_status":"not_applicable","legal_checked_at":null,"legal_note":null,"legal_source_url":null,"legal_canonical_names":[],"accepted_answers":null,"grading_mode":"standard","analysis_last_attempt_at":null},{"id":"R-111-2-18","subject":"社會工作研究方法","year":"111","round":"第二次","qno":"18","major":"統計檢定","topic":"迴歸分析 > 多元迴歸應用","keywords":"多元迴歸, 薪資所得, 相關因素, 卡方檢定, 因素分析","question":"承上題，此一研究可能使用下列何種統計分析方法？","opt_a":"多元迴歸分析","opt_b":"內容分析","opt_c":"因素分析","opt_d":"卡方檢定","answer":"A","exp_why":"(A)多元迴歸分析：以多個自變項共同預測連續依變項——承上題的設計用多元迴歸。","exp_others":"(B)內容分析是文本研究、(C)因素分析縮構面、(D)卡方是類別。","exp_trap":"統計方法選擇口訣:依變項連續+自變項2組→t檢定(同一批人前後測=相依/配對t;不同兩組=獨立t,先做變異數同質性檢定);自變項3組以上→變異數分析ANOVA(兩組時F=t平方,等價);兩個連續變項關聯→積差相關;兩個類別變項→卡方;多自變項預測連續依變項(含控制變項)→(多元)迴歸;依變項是類別→不可用迴歸(用判別/邏輯斯);縮題建構面→因素分析(探索性EFA建立構面;驗證性CFA檢驗既有結構)。","exp_raw":"","mnemonic":"統計選擇:依變項連續+2組→t檢定(配對/獨立);3組以上→ANOVA;兩連續變項關聯→積差相關;兩類別變項→卡方。","extension":"迴歸分析(多元迴歸)。","law":"","mistake":"概念混淆","source_exam_code":"111110","source_url":"https://wwwq.moex.gov.tw/exam/wHandExamQandA_File.ashx?c=105&code=111110&q=1&s=0406&t=Q","analysis_status":"ready","analysis_attempt