  item jsonb; observed jsonb;other_before jsonb;other_after jsonb;grading_before jsonb;grading_after jsonb;config_before jsonb;config_after jsonb;changed integer;
BEGIN
  IF (SELECT count(*) FROM public.questions)<>4800 THEN RAISE EXCEPTION 'P0 111-2 missing full corpus';END IF;
  SELECT jsonb_agg(to_jsonb(q) ORDER BY id) INTO other_before FROM public.questions q WHERE id NOT IN ('R-111-2-14','R-111-2-15','R-111-2-17','R-111-2-18','R-111-2-29','R-111-2-30');
  SELECT jsonb_agg(jsonb_build_array(id,answer,accepted_answers,grading_mode) ORDER BY id) INTO grading_before FROM public.questions;
  SELECT to_jsonb(c) INTO config_before FROM public.ai_analysis_job_config c WHERE id=true;
  IF config_before->>'enabled'<>'false' THEN RAISE EXCEPTION 'P0 111-2 AI config not off';END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(before_rows) LOOP
    SELECT to_jsonb(q) INTO STRICT observed FROM public.questions q WHERE id=item->>'id' FOR UPDATE;
    IF observed IS DISTINCT FROM item THEN RAISE EXCEPTION 'P0 111-2 preimage drift %',item->>'id';END IF;
  END LOOP;
  UPDATE public.questions SET question='情況：某社工想了解北部地區受聘在家中的外籍看護工照顧及生活適應的現況，他設計了一份網路問卷放到外籍移工常聯絡的群組或瀏覽的網站（Facebook 或 Line）上，讓在群組或網站看到此問卷的外籍看護工自由填寫。

承上題，此研究的資料蒐集方法最大的缺點為何？' WHERE id='R-111-2-14'; GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'P0 111-2 row count R-111-2-14';END IF;
  UPDATE public.questions SET question='情況：某社工想了解北部地區受聘在家中的外籍看護工照顧及生活適應的現況，他設計了一份網路問卷放到外籍移工常聯絡的群組或瀏覽的網站（Facebook 或 Line）上，讓在群組或網站看到此問卷的外籍看護工自由填寫。

承上題，若該社工也想要進一步了解北部地區移工失聯的現象，由於受訪對象隱匿（難以尋覓）的特性，下列何種方法適合？' WHERE id='R-111-2-15'; GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'P0 111-2 row count R-111-2-15';END IF;
  UPDATE public.questions SET question='情況：某研究者欲進行全國社會工作師之薪資所得相關因素探究，但研究經費有限。

承上題，該研究之分析單位為何？' WHERE id='R-111-2-17'; GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'P0 111-2 row count R-111-2-17';END IF;
  UPDATE public.questions SET question='情況：某研究者欲進行全國社會工作師之薪資所得相關因素探究，但研究經費有限。

承上題，此一研究可能使用下列何種統計分析方法？' WHERE id='R-111-2-18'; GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'P0 111-2 row count R-111-2-18';END IF;
  UPDATE public.questions SET question='情況：某學者想要針對 4 家平面媒體對於政府開放移工引進臺灣後這 16 年間（1992～2018 年）8,248 則相關報導為母體，研究者先將每篇報導以時間順序排列，形成一個抽樣架構後，以每 4 則抽取一則的方式抽出 2,062 篇新聞報導作為研究樣本，進而整理出臺灣主流媒體報導所塑造的移工形象。

承上題，此研究的分析單位為何？' WHERE id='R-111-2-29'; GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'P0 111-2 row count R-111-2-29';END IF;
  UPDATE public.questions SET question='情況：某學者想要針對 4 家平面媒體對於政府開放移工引進臺灣後這 16 年間（1992～2018 年）8,248 則相關報導為母體，研究者先將每篇報導以時間順序排列，形成一個抽樣架構後，以每 4 則抽取一則的方式抽出 2,062 篇新聞報導作為研究樣本，進而整理出臺灣主流媒體報導所塑造的移工形象。

承上題，這個研究所採用的研究方法為何？' WHERE id='R-111-2-30'; GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'P0 111-2 row count R-111-2-30';END IF;
  UPDATE public.questions SET analysis_status='review' WHERE id IN ('R-111-2-14','R-111-2-15','R-111-2-17','R-111-2-18','R-111-2-29','R-111-2-30') AND analysis_status='pending';
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>6 THEN RAISE EXCEPTION 'P0 111-2 AI review quarantine mismatch';END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(after_rows) LOOP
    SELECT to_jsonb(q) INTO STRICT observed FROM public.questions q WHERE id=item->>'id';
    IF observed IS DISTINCT FROM item THEN RAISE EXCEPTION 'P0 111-2 postimage drift %',item->>'id';END IF;
  END LOOP;
  SELECT jsonb_agg(to_jsonb(q) ORDER BY id) INTO other_after FROM public.questions q WHERE id NOT IN ('R-111-2-14','R-111-2-15','R-111-2-17','R-111-2-18','R-111-2-29','R-111-2-30');
  SELECT jsonb_agg(jsonb_build_array(id,answer,accepted_answers,grading_mode) ORDER BY id) INTO grading_after FROM public.questions;
  SELECT to_jsonb(c) INTO config_after FROM public.ai_analysis_job_config c WHERE id=true;
  IF other_before IS DISTINCT FROM other_after THEN RAISE EXCEPTION 'P0 111-2 unrelated row changed';END IF;
  IF grading_before IS DISTINCT FROM grading_after THEN RAISE EXCEPTION 'P0 111-2 grading changed';END IF;
  IF config_before IS DISTINCT FROM config_after THEN RAISE EXCEPTION 'P0 111-2 AI config changed';END IF;
  IF EXISTS (SELECT 1 FROM public.questions WHERE analysis_status='pending') THEN RAISE EXCEPTION 'P0 111-2 unreviewed pending';END IF;
  RAISE NOTICE 'SWSI 111-2 six row rollback rehearsal pass; other 4794 rows and all grading preserved';
END;
$swsi_1112_rehearsal$;
